using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Diagnostics;using System.Runtime.InteropServices;using System.Windows;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;
class GestureTests {
 static int failures,checks;static object Field(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}static void Set(object o,string n,object v){o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(o,v);}static void Call(object o,string n,params object[] a){o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,a);}static void Check(string n,bool ok){checks++;Console.WriteLine((ok?"PASS ":"FAIL ")+n);if(!ok)failures++;}
 [StructLayout(LayoutKind.Sequential)]struct Cursor{public int X,Y;}[DllImport("user32.dll")]static extern bool GetCursorPos(out Cursor p);[DllImport("user32.dll")]static extern bool SetCursorPos(int x,int y);
 static void Tick(object pet){var clock=(Stopwatch)Field(pet,"clock");Set(pet,"lastTick",clock.Elapsed.TotalSeconds-.08);Call(pet,"Tick",null,EventArgs.Empty);}
 [STAThread]static int Main(string[] args){var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Window pet=null;Cursor cursor;GetCursorPos(out cursor);try{pet=(Window)Activator.CreateInstance(typeof(ConanPet),true);pet.Show();((DispatcherTimer)Field(pet,"ticker")).Stop();((DispatcherTimer)Field(pet,"skillTicker")).Stop();SetCursorPos(0,0);var voice=(VoiceRuntime)Field(pet,"voices");voice.Stop();((BubbleQueue)Field(pet,"messages")).Clear();Set(pet,"nextIdleGesture",Double.MaxValue);Set(pet,"actionUntil",0.0);var sprites=(SpriteActions)Field(pet,"signature");var view=(SpriteView)Field(pet,"sprite");var clock=(Stopwatch)Field(pet,"clock");
  Check("20 distinct two-hand number poses",Enumerable.Range(1,20).Select(n=>sprites.Frame("count",.5,n)).Distinct().Count()==20);foreach(int n in new[]{6,9,10,11,15,16,19,20}){Call(pet,"PlayIdle","count");Set(pet,"signatureCount",n);Set(pet,"signatureStart",clock.Elapsed.TotalSeconds-.3);Tick(pet);Check("actual number rendering "+n,Object.ReferenceEquals(view.Frame,sprites.Frame("count",0,n)));}
  Call(pet,"SetMovement","roam");var choices=new HashSet<int>();for(int i=0;i<ActionTiming.IdleActions.Length;i++){Call(pet,"RandomIdle");choices.Add((int)Field(pet,"lastIdle"));}Check("random round visits every action",choices.Count==ActionTiming.IdleActions.Length);
  Call(pet,"SetMovement","rest");Set(pet,"signatureUntil",0.0);((BubbleQueue)Field(pet,"messages")).Clear();pet.Left=400;pet.Top=300;double x=pet.Left,y=pet.Top;Call(pet,"PlaySignature","skate",2.4,false);Tick(pet);Check("skate demonstration moves X and Y",pet.Left!=x&&pet.Top!=y);Check("skate demonstration plans a longer trip",Math.Sqrt(Math.Pow((double)Field(pet,"targetX")-x,2)+Math.Pow((double)Field(pet,"targetY")-y,2))>300);Check("skate demonstration allows full trip time",(double)Field(pet,"skateDemoUntil")-(double)Field(pet,"motionStart")>=7.2-1e-6);Check("moving skateboard frame rendered",Enumerable.Range(0,sprites.Count("skate")).Any(i=>Object.ReferenceEquals(view.Frame,sprites.Frame("skate",(i+.1)/sprites.Count("skate")))));
  Set(pet,"targetX",pet.Left-40);Set(pet,"targetY",pet.Top-30);Tick(pet);Check("left travel mirrors skateboard",(bool)Field(view,"mirrored"));Set(pet,"walkUntil",0.0);Set(pet,"skateDemoUntil",0.0);Set(pet,"nextWalk",Double.MaxValue);Set(pet,"signatureUntil",0.0);Set(pet,"actionUntil",0.0);Tick(pet);Check("stationary pet leaves skating frames",!Enumerable.Range(0,sprites.Count("skate")).Any(i=>Object.ReferenceEquals(view.Frame,sprites.Frame("skate",(i+.1)/sprites.Count("skate")))));
  var savedRandom=(Random)Field(pet,"random");var area=(Rect)typeof(ConanPet).GetMethod("WorkArea",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(pet,null);var expected=new Random(42);double expectedX=area.Left+expected.NextDouble()*Math.Max(0,area.Width-pet.Width),expectedY=area.Top+expected.NextDouble()*Math.Max(0,area.Height-pet.Height);
  pet.Left=400;pet.Top=300;Call(pet,"SetMovement","roam");Set(pet,"random",new Random(42));Set(pet,"nextWalk",0.0);Tick(pet);double walkDistance=Math.Sqrt(Math.Pow((double)Field(pet,"targetX")-400,2)+Math.Pow((double)Field(pet,"targetY")-300,2));Check("walking retains existing destination selection",Math.Abs((double)Field(pet,"targetX")-expectedX)<.001&&Math.Abs((double)Field(pet,"targetY")-expectedY)<.001);
  pet.Left=400;pet.Top=300;Call(pet,"SetMovement","skate");Set(pet,"random",new Random(42));Set(pet,"nextWalk",0.0);Tick(pet);double skateDistance=Math.Sqrt(Math.Pow((double)Field(pet,"targetX")-400,2)+Math.Pow((double)Field(pet,"targetY")-300,2));Check("skate cruising chooses longer travel than walking",skateDistance>walkDistance+1);Set(pet,"random",savedRandom);Call(pet,"SetMovement","rest");
  Call(pet,"PlaySignature","bowtie",2.4,false);var lead=sprites.PlaybackFrame("bowtie",.5,2.4,0,null);Check("bowtie middle holds instead of ping pong",Object.ReferenceEquals(lead,sprites.PlaybackFrame("bowtie",1.5,2.4,0,null)));Call(pet,"Animate",3);Check("manual original gesture interrupts idle performance",(double)Field(pet,"signatureUntil")==0);
  Directory.CreateDirectory(args[0]);Call(pet,"PlaySignature","kick",2.4,false);double duration=(double)Field(pet,"signatureUntil")-(double)Field(pet,"signatureStart");Check("volley plays natural complete duration",duration>=1.2&&duration<2.4);for(int i=0;i<sprites.Count("kick");i++){double start=clock.Elapsed.TotalSeconds-(i+.1)*.16;Set(pet,"signatureStart",start);Set(pet,"signatureUntil",start+duration);Tick(pet);pet.UpdateLayout();var image=new RenderTargetBitmap((int)view.ActualWidth,(int)view.ActualHeight,96,96,PixelFormats.Pbgra32);var drawing=new DrawingVisual();using(var dc=drawing.RenderOpen())dc.DrawRectangle(new VisualBrush(view){Stretch=Stretch.Fill},null,new Rect(0,0,image.PixelWidth,image.PixelHeight));image.Render(drawing);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(image));using(var f=File.Create(Path.Combine(args[0],"v5.5-volley-"+i.ToString("D2")+".png")))png.Save(f);}
 }catch(Exception e){Console.WriteLine(e);failures++;}finally{SetCursorPos(cursor.X,cursor.Y);if(pet!=null)pet.Close();app.Shutdown();}Console.WriteLine("Checks: "+checks+" Failures: "+failures);return failures==0?0:1;}
}
